class AsyncMutex {
  constructor() {
    this._locked = false;
    this._waitingQueue = [];
  }

  acquire() {
    return new Promise(resolve => {
      if (!this._locked) {
        this._locked = true;
        resolve(this._createReleaser());
      } else {
        this._waitingQueue.push(resolve);
      }
    });
  }

  _createReleaser() {
    return () => {
      if (this._waitingQueue.length > 0) {
        const nextResolve = this._waitingQueue.shift();
        nextResolve(this._createReleaser());
      } else {
        this._locked = false;
      }
    };
  }
}

