          const selectClause = clauses.selects.length > 0 ? clauses.selects.join(", ") : "*";
          let sql = `SELECT ${selectClause} FROM ${clauses.table}`;
          if (clauses.where.length > 0) {
            sql += " WHERE " + clauses.where.map(w => `${w.col} = '${w.val}'`).join(" AND ");
